tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync, copyFileSync } from 'node:fs';
import { join } from 'node:path';

const scratch = mkdtempSync(join(process.cwd(), '.acceptance-data.'));
const api = \"import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs';\";
function run(code, ...args) {
  return execFileSync(process.execPath, ['--input-type=module', '-e', api + code, ...args], { encoding: 'utf8' }).trim();
}
const reload = path => JSON.parse(run('console.log(JSON.stringify(loadCatalog(process.argv[1])));', path));
const raw = path => JSON.parse(readFileSync(path, 'utf8'));
try {
  const initial = raw('catalog/fixture/catalog.json');
  for (const [id, flag] of [['a', 'true'], ['b', 'false']]) {
    const path = join(scratch, id + '.json');
    copyFileSync('catalog/fixture/catalog.json', path);
    assert.deepEqual(reload(path), initial);
    run('const [path, id, flag] = process.argv.slice(1); saveCatalog(path, setPinned(loadCatalog(path), id, JSON.parse(flag)));', path, id, flag);
    const expected = initial.map(card => card.id === id ? { ...card, pinned: JSON.parse(flag) } : card);
    assert.deepEqual(raw(path), expected);
    const records = reload(path);
    assert.deepEqual(records, expected);
    console.log('Independent save and reload', id, flag, JSON.stringify(records));
  }

  const path = join(scratch, 'legacy.json');
  const legacy = [{ id: 'old', title: 'Старая карточка' }, { id: 'next', title: 'Next', pinned: true }];
  writeFileSync(path, JSON.stringify(legacy));
  const normalized = [{ ...legacy[0], pinned: false }, legacy[1]];
  assert.deepEqual(reload(path), normalized);
  console.log('Legacy reload', JSON.stringify(normalized));

  const before = readFileSync(path);
  const error = run("'`const path = process.argv[1];
try { saveCatalog(path, setPinned(loadCatalog(path), '"'missing', true)); }
catch (error) { console.log(error.message); }"'`, path);
  assert.equal(error, '"'Unknown card: missing');
  assert.deepEqual(readFileSync(path), before);
  console.log('Missing id', error, 'file unchanged');

  const duplicates = join(scratch, 'duplicates.json');
  writeFileSync(duplicates, JSON.stringify([
    { id: 'same', title: 'First', pinned: false },
    { id: 'same', title: 'Second', pinned: false }
  ]));
  run('const path = process.argv[1]; saveCatalog(path, setPinned(loadCatalog(path), \"same\", true));', duplicates);
  console.log('Duplicate ID observation', JSON.stringify(reload(duplicates)));
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
NODE"

/bin/bash -lc "node --input-type=module <<'NODE'
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
const cache = mkdtempSync(join(process.cwd(), '.acceptance-npm.'));
try {
  const run = spawnSync('npm', ['test'], {
    cwd: join(process.cwd(), 'catalog'),
    env: { ...process.env, npm_config_cache: cache, npm_config_update_notifier: 'false' },
    stdio: 'inherit',
  });
  if (run.error) throw run.error;
  process.exitCode = run.status ?? 1;
} finally {
  rmSync(cache, { recursive: true, force: true });
}
NODE"

